package org.robolectric.internal.bytecode;
import java.io.*;import java.nio.file.*;import java.time.Instant;import java.util.*;
public final class RefusalTraceProbe {
 private static volatile String test="UNATTRIBUTED";
 private static String q(Object o){String s=String.valueOf(o);StringBuilder b=new StringBuilder("\"");for(char c:s.toCharArray()){switch(c){case '"':b.append("\\\"");break;case '\\':b.append("\\\\");break;case '\n':b.append("\\n");break;case '\r':b.append("\\r");break;case '\t':b.append("\\t");break;default:if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}
 private static String stat(File f){if(f==null)return "null";File[] a=f.listFiles();StringBuilder b=new StringBuilder(f.getAbsolutePath()+"[exists="+f.exists()+",dir="+f.isDirectory()+",len="+f.length()+"]");if(a!=null){Arrays.sort(a,Comparator.comparing(File::getName));for(int i=0;i<Math.min(20,a.length);i++)b.append(" ").append(a[i].getName()).append(":").append(a[i].isDirectory()?"D":"F").append(":").append(a[i].length());}return b.toString();}
 private static String root(Object receiver){try{if(receiver==null)return "STATIC";var f=receiver.getClass().getDeclaredField("recordingRoot");f.setAccessible(true);File r=(File)f.get(receiver);if(r==null)return "NO_ROOT";return stat(r)+" | "+stat(new File(r.getParentFile(),"backup-replace-"+r.getName()+"-workspace"))+" | "+stat(new File(r.getParentFile(),"backup-replace-"+r.getName()+".json"));}catch(Throwable t){return "ROOT_OBSERVATION_UNAVAILABLE:"+t.getClass().getName();}}
 private static synchronized void emit(String kind,String method,int line,String value,Object receiver){try{String d=System.getProperty("audit.refusal.trace");if(d==null)return;long pid=ProcessHandle.current().pid();String row="{\"atUtc\":"+q(Instant.now())+",\"nano\":"+System.nanoTime()+",\"pid\":"+pid+",\"thread\":"+q(Thread.currentThread().getName())+",\"threadId\":"+Thread.currentThread().threadId()+",\"receiverId\":"+System.identityHashCode(receiver)+",\"test\":"+q(test)+",\"kind\":"+q(kind)+",\"method\":"+q(method)+",\"line\":"+line+",\"value\":"+q(value)+",\"rootMetadata\":"+q(root(receiver))+"}\n";Files.writeString(Path.of(d,"trace-"+pid+".jsonl"),row,StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(Throwable t){System.err.println("AUDIT_TRACE_ERROR "+t.getClass().getName());}}
 public static void test(String name){test=name;emit("TEST_ENTER",name,-1,"",null);}
 private static String stack(){StringBuilder b=new StringBuilder();for(var s:Thread.currentThread().getStackTrace())b.append(s).append(" | ");return b.toString();}
 private static boolean wanted(Object p){String s=String.valueOf(p);return s.contains("robolectric-Unit3GenderTeachingTest")||s.contains("backup-replace-recordings");}
 public static void deleting(Object p,String m){if(wanted(p))emit("DELETE_ENTER",m,-1,String.valueOf(p)+" | "+stack(),null);}
 public static void deleted(boolean ok,Object p,String m){if(wanted(p))emit(ok?"DELETE_SUCCESS":"DELETE_FALSE",m,-1,String.valueOf(p),null);}
 public static void deletedVoid(Object p,String m){if(wanted(p))emit("DELETE_SUCCESS",m,-1,String.valueOf(p),null);}
 public static void enter(String method,int line,Object self){emit("ENTER",method,line,"self="+System.identityHashCode(self)+" | "+stack(),self);}
 public static void result(Object value,String method,int line,Object self){emit("ARETURN",method,line,value==null?"null":value.getClass().getName()+"@"+System.identityHashCode(value)+(value instanceof Enum<?>?":"+value.toString():""),self);}
 public static void integer(int value,String method,int line,Object self){emit("IRETURN",method,line,Integer.toString(value),self);}
 public static void caught(Throwable t,String method,int line,Object self){StringBuilder b=new StringBuilder(t.getClass().getName()+":"+String.valueOf(t.getMessage()));if(b.length()>400)b.setLength(400);StackTraceElement[] s=t.getStackTrace();for(int i=0;i<Math.min(12,s.length);i++)b.append(" | ").append(s[i]);emit("CAUGHT",method,line,b.toString(),self);}
}